import SwiftUI

/// Design tokens — generated by hand from replica/design/tokens.json.
/// Role names match the JSON; change values there first, re-run contrast.py, then here.
enum Theme {
    enum C {
        static let bg = Color(hex: 0xF7F2E8)
        static let surface = Color(hex: 0xFFFDF8)
        static let border = Color(hex: 0xE4DACB)
        static let borderInput = Color(hex: 0x8A7F70)
        static let text = Color(hex: 0x1E2230)
        static let textMuted = Color(hex: 0x5F6573)
        static let accent = Color(hex: 0x8C2F39)
        static let onAccent = Color(hex: 0xFFFFFF)
        static let accentSoft = Color(hex: 0xF3E3E1)
        static let danger = Color(hex: 0xB3261E)
        static let success = Color(hex: 0x2E6B4F)
        static let warning = Color(hex: 0x8A5A00)
        static let cell = Color(hex: 0xFFFFFF)
        static let cellText = Color(hex: 0x1E2230)
        static let cellActive = Color(hex: 0xF1DFC0)
        static let cellHint = Color(hex: 0xE9C46A)
        static let cellSolved = Color(hex: 0x2E5E4E)
        static let onCellSolved = Color(hex: 0xFFFFFF)
        static let key = Color(hex: 0xFFFFFF)
        static let keyText = Color(hex: 0x1E2230)
        static let keyUsed = Color(hex: 0xE4DACB)
        static let keyUsedText = Color(hex: 0x544D42)
        static let coin = Color(hex: 0xE9C46A)
        static let onCoin = Color(hex: 0x1E2230)
    }

    enum R {
        static let cell: CGFloat = 6
        static let key: CGFloat = 10
        static let card: CGFloat = 16
    }

    enum S {
        static let xs: CGFloat = 4, sm: CGFloat = 8, md: CGFloat = 12, lg: CGFloat = 16, xl: CGFloat = 24, xxl: CGFloat = 32
        static let cellMax: CGFloat = 40, cellGap: CGFloat = 3, key: CGFloat = 46, slot: CGFloat = 44, topbar: CGFloat = 52
    }

    /// Noto Naskh Arabic (SIL OFL 1.1), bundled as a variable font.
    static let arabicFamily = "Noto Naskh Arabic"

    static func arabic(_ size: CGFloat, _ weight: Font.Weight = .regular) -> Font {
        .custom(arabicFamily, size: size).weight(weight)
    }

    enum F {
        static let caption = Theme.arabic(13, .medium)
        static let body = Theme.arabic(17)
        static let clue = Theme.arabic(22, .semibold)
        static let title = Theme.arabic(22, .bold)
        static let cell = Theme.arabic(22, .bold)
        static let key = Theme.arabic(26, .semibold)
        static let display = Theme.arabic(40, .bold)
        static let number = Font.system(size: 17, weight: .bold, design: .rounded)
    }
}

extension Color {
    init(hex: UInt32) {
        self.init(.sRGB,
                  red: Double((hex >> 16) & 0xFF) / 255,
                  green: Double((hex >> 8) & 0xFF) / 255,
                  blue: Double(hex & 0xFF) / 255,
                  opacity: 1)
    }
}

extension View {
    func cardShadow() -> some View {
        shadow(color: Color(hex: 0x1E2230).opacity(0.06), radius: 1, y: 1)
            .shadow(color: Color(hex: 0x1E2230).opacity(0.08), radius: 6, y: 2)
    }
}
